import sys, json, time, os
import numpy as np

def read_instance(path):
    with open(path) as f:
        data = json.load(f)
    n = data["n"]
    A = np.array(data["A"], dtype=np.int64)
    B = np.array(data["B"], dtype=np.int64)
    return n, A, B

def compute_cost(p, A, B):
    return np.sum(A * B[p][:, p])

def local_search(n, A, B, budget):
    start = time.time()
    p = list(range(n))
    best_cost = compute_cost(p, A, B)
    best_p = p[:]
    while time.time() - start < budget:
        improved = False
        for i in range(n):
            for j in range(i+1, n):
                p[i], p[j] = p[j], p[i]
                new_cost = compute_cost(p, A, B)
                if new_cost < best_cost:
                    best_cost = new_cost
                    best_p = p[:]
                    improved = True
                else:
                    p[i], p[j] = p[j], p[i]
                if time.time() - start >= budget:
                    break
            if time.time() - start >= budget:
                break
        if not improved:
            break
    return best_p, best_cost

def main():
    if len(sys.argv) < 3:
        return
    path = sys.argv[1]
    budget = float(sys.argv[2])
    if "QAP_TIME_LIMIT_S" in os.environ:
        budget = min(budget, float(os.environ["QAP_TIME_LIMIT_S"]))
    n, A, B = read_instance(path)
    perm, _ = local_search(n, A, B, budget)
    print("PERMUTATION: " + " ".join(str(x+1) for x in perm))

if __name__ == "__main__":
    main()

